def round_to_sig_figs(x, sig_figs):
    if x == 0:
        return 0
    # Get the exponent
    exp = math.floor(math.log10(abs(x)))
    # Scale to get the significant digits
    scaled = x / (10 ** (sig_figs - 1 - exp))
    rounded_scaled = round(scaled, sig_figs - 1)
    return rounded_scaled * (10 ** (sig_figs - 1 - exp))

