def round_to_sig_figs(x, sig_figs):
    if x == 0:
        return 0
    if sig_figs == 1:
        return round(x, 0)
    # Count digits before decimal
    if x >= 1:
        decimal_places = sig_figs - 1 - int(math.floor(math.log10(abs(x))))
    else:
        decimal_places = sig_figs - 1 - int(math.ceil(math.log10(abs(x))))
