def to_6_sig_figs(x):
    if x == 0:
        return 0
    # Count significant figures
    s = f'{x:.10f}'.strip('0')
    if not s:
        return 0
    # Find where significant figures start
    if '.' in s:
        int_part, frac_part = s.split('.')
        if int_part == '':
            int_part = '0'
        # Count from first non-zero digit
        sig_count = 0
        for i, c in enumerate(int_part + frac_part):
            if c != '0':
                sig_count = i + 1
                break
        # We need 6 significant figures
        if sig_count <= 6:
            return float(s[:sig_count + 6])
        else:
            return float(s[:sig_count + 6])
    else:
        return float(s[:6])

