# Round to 6 significant figures
# For numbers less than 1, we count significant figures starting from the first non-zero digit
def sig_figs(x, n):
    if x == 0:
        return 0
    s = str(abs(x))
    if '.' in s:
        integer_part, decimal_part = s.split('.')
        if len(integer_part) == 1 and integer_part == '0':
            # First significant figure is in decimal part
            sig_digits = decimal_part[:n]
            if len(sig_digits) < n:
                sig_digits = sig_digits + '0' * (n - len(sig_digits))
            # Round
            sig_digits = sig_digits[:-1] + str(round(float(sig_digits), 1))
            return -float(sig_digits) if x < 0 else float(sig_digits)
        else:
            sig_digits = s[:n]
            return float(sig_digits)
    else:
        sig_digits = s[:n]
        return float(sig_digits)

