        for c in s:
            if c == '.':
                continue
            if c == '0' and sig_count == 0:
                continue
            sig_count += 1
        # We need n significant figures
        if sig_count < n:
            return round(float(s), n - sig_count)
        else:
            return round(float(s), n - sig_count)
    else:
        return round(float(s), n)

