def sig_figs(x, n):
    if x == 0:
        return 0
    s = str(abs(x))
    # Count digits before decimal point
    if '.' in s:
        before, after = s.split('.')
        total_digits = len(before) + len(after)
    else:
        total_digits = len(s)
    # We want n significant figures
    if total_digits <= n:
        return round(x, n)
    else:
        # Round to n significant figures
        # Find the position to round
        if '.' in s:
            before, after = s.split('.')
            # Position is len(before) - n + 1
            pos = len(before) - n + 1
            return round(float(s), -pos)
        else:
            return round(float(s), -n)

