def sig_figs(x, n=6):
    if x == 0:
        return 0
    s = f"{abs(x):.10f}"
    # Count significant figures
    if '.' in s:
        integer_part, decimal_part = s.split('.')
        sig_count = len(integer_part) + len(decimal_part)
    else:
        sig_count = len(s)

    # Round to n significant figures
    if sig_count <= n:
        return float(s)
    else:
        # Find the position to round
        if '.' in s:
            integer_part, decimal_part = s.split('.')
            # We need to keep n significant figures total
            # integer_part has len(integer_part) figures, so we need n - len(integer_part) more from decimal
            decimal_part = decimal_part[:n - len(integer_part)]
            if len(decimal_part) < n - len(integer_part):
                decimal_part = decimal_part + '0' * (n - len(integer_part) - len(decimal_part))
            return float(integer_part + '.' + decimal_part)
        else:
            return float(s[:n])

